from ui_persistent import *
record(P+'Views/TreasuryView.xaml','Treasury account positions, searchable ledger and money movement overlay.',[
 ('Balances','176x78 wrapping balance buttons filter by account; account label mapped Arabic. Outside-money pane min300 separately explains pending transfers and driver custody rather than including them in held balance.'),
 ('FilterByAccountCommand','All-accounts reset plus240px text filter; actual server query scope and100row limit in API mean search may cover only loaded movements. No paging/date controls visible; empty copy says every movement, potentially overstates completeness.'),
 ('Movements','Type/source/destination/amount/date/details including actor+reference supports traceability. Fixed650px columns plus detailstar, eager ItemsControl/vertical scroll. Amounts formatted from server integer values, no ledger edits.'),
 ('IsActionOpen','460max680 full scroll, deposit/withdraw funding accounts distinct from transferAllAccounts. Amount/reason/reference and managerPIN disabledCanEditAction. External funding restrictions stated but actual server validation independent.'),
 ('SubmitTreasuryActionCommand','Static execute caption with no separate process-recovered pending panel. UI001 prior memory-only treasury request concern not cured by disabled fields. No monetary write executed.'),
 ('ActionNote','White unwrapped toast on TextPrimary theme brush: dark lowcontrast and longnote overflow risk. Refresh icon no explicit accessible name; no standalone focus trap.')
 ],'NOT_EXECUTED. Need exact retry/global navigation/restart, account filtering with capped history, source/destination constraints, native small viewport and dark feedback. No callable XAML declarations.', 'Expose ledger coverage/paging and pending action context. Keep outside money separate and use semantic toast pair.')
record(P+'Views/DailySummaryView.xaml','Read-only operational daily sheet from server reconciliation and employee ledger.',[
 ('HasSummary','Single vertically scrollable max900 sheet, no date selector or print/export button. Source comment explicitly identifies report-print pipeline gap; no actual printer output available from this view.'),
 ('Settings.SubName','Restaurant identity fromSettings but appends fixed24hour-service claim, not settings-derived. Signature lines are blank visual pen lines, not authenticated approvals.'),
 ('Summary.Sales.NetSalesPiastres','Net sales plus payment channels/ordercount and ordertype breakdown distinct fields. Six equal columns with padded cards use unwrapped labels, risk crowding at narrow widths/large fonts. Collected versus pending transfer not made explicit here as on owner dashboard.'),
 ('NetShiftDifferencePiastres','Cash section displays expenses, employee cashout combined and shift difference; totals sourceVM/server. Cannot infer full cash reconciliation merely because same sheet presents these three.'),
 ('Summary.EmployeeLedger.OvertimePiastres','Label says overtime hours but binding is money converted to EGP. Source-confirmed unit/label mismatch; number is not an hour count. Adjacent wage/advance/withdrawal are currency appropriately.'),
 ('CashierNamesDisplay','Actual cashier names plus cashier title, manager/owner signature lines fixed140width. No persisted signature/auth state, no name invented.'),
 ('HasNoBusinessDay','Distinct legitimate no-businessday with ControlCenter instruction; spinner/error/retry. No mock fallback document. Refresh icon lacks explicit accessible name.')
 ],'NOT_EXECUTED. Need cross-report reconciliation, timezone/currentday selection, six-column scaling, overtime units, pending-money label and actual report-print requirements. No callable declarations.', 'Correct overtime unit copy in approved fix; disclose read-only/no print/export capability and avoid hardcoded24hour claim if restaurant hours differ.')
